    for n in CLEAN_METRICS:
        before = np.mean([_call(misorder_rate, a, r) for a, r in raw[n]])
        after = np.mean([_call(misorder_rate, a, r) for a, r in scored[n]])
        print(f"  {n:<16} {before:.3f} -> {after:.3f}")


